export enum Suit {
  Spades = '♠',
  Clubs = '♣',
  Hearts = '♥',
  Diamonds = '♦',
}

export enum Color {
  Black = 'BLACK', // Physical
  Red = 'RED', // Magical
}

export enum Rank {
  Two = '2',
  Three = '3',
  Four = '4',
  Five = '5',
  Six = '6',
  Seven = '7',
  Eight = '8',
  Nine = '9',
  Ten = '10',
  Jack = 'J',
  Queen = 'Q',
  King = 'K',
  Ace = 'A',
}

export interface Card {
  id: string;
  suit: Suit;
  rank: Rank;
  numericValue: number; // 2-10, J=11, Q=12, K=13, A=1
  cost: number;
  baseColor: Color;
}

export interface FieldCard {
  instanceId: string;
  card: Card;
  ownerId: number;
  isTapped: boolean;
  isSummoningSick: boolean;
  attachedCards: Card[]; // For Queens
  currentHealth: number; // Usually equals attack, but for tracking state
}

export enum Phase {
  INIT = 'INIT',
  INIT_SELECT = 'INIT_SELECT', // New phase for selecting starting resources
  UPKEEP = 'UPKEEP',
  DRAW = 'DRAW',
  RESOURCE_START = 'RESOURCE_START',
  RESOURCE_ADD_SELECT = 'RESOURCE_ADD_SELECT',
  RESOURCE_SWAP_SELECT_HAND = 'RESOURCE_SWAP_SELECT_HAND',
  RESOURCE_SWAP_SELECT_PILE = 'RESOURCE_SWAP_SELECT_PILE',
  MAIN = 'MAIN',
  ATTACK_DECLARE = 'ATTACK_DECLARE',
  BLOCK_DECLARE = 'BLOCK_DECLARE',
  DAMAGE = 'DAMAGE',
  GAME_OVER = 'GAME_OVER',
}

export interface PlayerState {
  id: number;
  name: string;
  isCpu?: boolean;
  life: number;
  hand: Card[];
  library: Card[]; // Deck for Pro mode
  resources: FieldCard[]; // Changed from Card[] to FieldCard[] to support tapping
  field: FieldCard[];
  discard: Card[];
  consecutiveDrawFailures: number;
  hasAttackedThisTurn: boolean;
}

export type GameMode = 'STREET' | 'PRO' | 'SANDBOX' | 'TUTORIAL';

export interface LogEntry {
    id: string;
    text: string;
}

export interface TutorialStep {
    id: string;
    instructionText: string;
    // Helper to find the DOM element to highlight
    highlightElementId?: string; 
    highlightMode?: 'MASK' | 'OUTLINE' | 'NONE'; // New: Control highlight style
    // What enables the next step?
    requiredAction: 'CLICK_CARD' | 'CLICK_UI_BUTTON' | 'PLAY_CARD' | 'PHASE_CHANGE' | 'NONE'; 
    targetId?: string; // Specific ID required for the action (e.g., card ID)
    allowedInteractionIds: string[]; // Whitelist of IDs user can interact with
}

