import { Card, Suit, Rank, Color, FieldCard, PlayerState, GameState, Phase, TutorialStep } from './types';
import { CARD_VALUES, MAX_RESOURCES } from './constants';

// Unique ID generator
export const generateId = () => Math.random().toString(36).substr(2, 9);

export const createDeck = (): Card[] => {
  const suits = [Suit.Spades, Suit.Clubs, Suit.Hearts, Suit.Diamonds];
  const ranks = Object.values(Rank);
  const deck: Card[] = [];

  for (const suit of suits) {
    for (const rank of ranks) {
      const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
      const numericValue = CARD_VALUES[rank];

      // Cost is equal to numeric value, except Ace=1, J=2, Q=3, K=4
      let cost = numericValue;
      if (rank === Rank.Jack) cost = 2;
      if (rank === Rank.Queen) cost = 3;
      if (rank === Rank.King) cost = 4;
      if (rank === Rank.Ace) cost = 1;

      deck.push({
        id: generateId(),
        suit,
        rank,
        numericValue,
        cost,
        baseColor
      });
    }
  }
  return shuffle(deck);
};

export const createTutorialDeck = (): Card[] => {
    // A fixed, non-shuffled deck for predictable tutorial scenarios.
    // Order: P1 Hand (8), P2 Hand (8), P1 Draw, P2 Draw...

    const card = (rank: Rank, suit: Suit): Card => {
        const baseColor = (suit === Suit.Spades || suit === Suit.Clubs) ? Color.Black : Color.Red;
        let cost = CARD_VALUES[rank];
        if (rank === Rank.Jack) cost = 2;
        if (rank === Rank.Queen) cost = 3;
        if (rank === Rank.King) cost = 4;
        if (rank === Rank.Ace) cost = 1;

        return {
            id: `tut-${rank}-${suit}`, // Fixed IDs for tutorial
            rank, suit, numericValue: CARD_VALUES[rank], cost, baseColor
        };
    };

    return [
        // P1 Hand (8) - Heavy Resources, 1 Attacker
        card(Rank.Ten, Suit.Spades),
        card(Rank.Nine, Suit.Spades),
        card(Rank.Eight, Suit.Spades), // Res 3
        card(Rank.Seven, Suit.Diamonds), // Res 4
        card(Rank.Five, Suit.Hearts), // Attacker
        card(Rank.Ace, Suit.Spades), 
        card(Rank.King, Suit.Diamonds),
        card(Rank.Queen, Suit.Clubs),

        // P2 Hand (8) - Passive Setup
        card(Rank.Ten, Suit.Hearts),
        card(Rank.Nine, Suit.Hearts),
        card(Rank.Eight, Suit.Hearts),
        card(Rank.Seven, Suit.Clubs),
        card(Rank.Two, Suit.Spades),
        card(Rank.Three, Suit.Diamonds),
        card(Rank.Ace, Suit.Diamonds),
        card(Rank.King, Suit.Spades),

        // P1 Draws
        card(Rank.Six, Suit.Spades),
        // P2 Draws
        card(Rank.Six, Suit.Hearts),
    ];
};

