        makeCard(Rank.Eight, Suit.Spades),
        makeCard(Rank.Seven, Suit.Diamonds),
        makeCard(Rank.Five, Suit.Hearts),
        makeCard(Rank.Ace, Suit.Spades), 
        makeCard(Rank.King, Suit.Diamonds),
        makeCard(Rank.Queen, Suit.Clubs),
    ];
};

