                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  attachedCards={fc.attachedCards}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                       <div className="bg-red-900/20 p-4 rounded-xl border border-red-900/30 flex gap-2 min-w-[100px] min-h-[120px] justify-center shadow-inner">
                           {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                               <CardDisplay 
                                  key={fc.instanceId} 
                                  domId={fc.instanceId}
                                  data-instance-id={fc.instanceId}
                                  card={fc.card} 
                                  isTapped={fc.isTapped}
                                  isSummoningSick={fc.isSummoningSick} 
                                  isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                  isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                  isLunging={gameState.activeCombatCardId === fc.instanceId}
                                  damageTaken={gameState.recentDamage[fc.instanceId]}
                                  attachedCards={fc.attachedCards}
                                  onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                  isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                  orientation="bottom"
                               />
                           ))}
                       </div>
                   </div>

                   <div id={`resource-container-${bottomPlayer.id}`} className="flex flex-col gap-2 items-center bg-black/20 p-2 rounded-lg border border-slate-700/30">
                       <div className="flex items-center gap-2">
                           <div className="text-[10px] text-indigo-400 font-bold uppercase">Resources</div>
                           <div className="text-xs font-bold text-indigo-400">
                               {bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}
                           </div>
                       </div>
                       <div className="grid grid-cols-2 gap-4 scale-90 origin-top">
                            <div className="flex flex-col -space-y-20 relative z-10">
                                 {bottomPlayer.resources.slice(0, 5).map((r, i) => (
                                     <div key={r.instanceId} id={r.instanceId} style={{ zIndex: i }} className="transition-all cursor-pointer hover:z-50 hover:scale-105 hover:-translate-y-2" onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}>
                                         <CardDisplay card={r.card} isTapped={r.isTapped} size="md" isSummoningSick={false} />
                                     </div>
                                 ))}
                            </div>
                            <div className="flex flex-col -space-y-20 relative z-0">
                                 {bottomPlayer.resources.slice(5, 10).map((r, i) => (
                                     <div key={r.instanceId} id={r.instanceId} style={{ zIndex: i }} className="transition-all cursor-pointer hover:z-50 hover:scale-105 hover:-translate-y-2" onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}>
                                         <CardDisplay card={r.card} isTapped={r.isTapped} size="md" isSummoningSick={false} />
                                     </div>
                                 ))}
                            </div>
                       </div>
                   </div>

               </div>
          </div>

          {dragState && dragState.sourceType === 'HAND' && (
              <div 
                className="fixed pointer-events-none z-[100]"
                style={{ left: dragState.currentX, top: dragState.currentY, transform: 'translate(-50%, -50%) rotate(5deg)' }}
              >
                  <CardDisplay card={dragState.cardObj!} size="md" isDragging />
              </div>
          )}
      </div>

      <div className="h-56 bg-slate-900 border-t border-slate-800 flex shadow-2xl z-30 flex-none">
          <div className="w-56 p-4 border-r border-slate-800 bg-slate-900 flex flex-col justify-between shrink-0">
              <div>
                  <h2 className="text-indigo-300 font-bold truncate">{bottomPlayer.name}</h2>
                  <div id="bottom-life-total" className="flex items-center gap-2 text-4xl font-black text-red-500 mt-2" ref={bottomLifeRef}>
                      <Heart size={32} fill="currentColor" /> {bottomPlayer.life}
                  </div>
              </div>
              <div className="flex flex-col gap-2">
                  <div className="text-xs text-slate-500 uppercase font-bold tracking-wider" ref={bottomDeckRef}>
                      Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span>
                  </div>
                  {/* Bottom Discard Button */}
                  <button 
                      onClick={() => setViewingDiscard(gameState.mode === 'STREET' ? 'SHARED' : bottomPlayer.id)}
                      className="flex items-center justify-center gap-2 bg-slate-800 hover:bg-slate-700 py-1.5 rounded text-xs text-slate-400 font-bold transition-colors border border-slate-700 w-full"
                  >
                      <Trash2 size={14} /> 
                      {gameState.mode === 'STREET' ? 'Shared Graveyard' : 'Graveyard'}
                      <span className="ml-auto bg-slate-900 px-1.5 rounded">
                        {gameState.mode === 'STREET' ? gameState.players[0].discard.length + gameState.players[1].discard.length : bottomPlayer.discard.length}
                      </span>
                  </button>
              </div>
          </div>

          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner min-w-0" ref={handRef}>
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);

                       let hasValidTarget = true;
                       if (c.rank === 'K') {
                           // King Validation: Needs enemy unit of same spectrum
                           hasValidTarget = topPlayer.field.some(f => getEffectiveColor(f) === c.baseColor);
                       }
                       if (c.rank === 'Q') {
                           // Queen Validation: Needs ANY unit on board
                           hasValidTarget = topPlayer.field.length > 0 || bottomPlayer.field.length > 0;
                       }

                       const isPlayable = isMainPhase && isInteractive && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost && hasValidTarget;

                       return (
                           <div key={c.id} id={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}>
                               <CardDisplay 
                                  card={c} 
                                  onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)}
                                  onMouseDown={(e) => handleDragStart(e, c, 'HAND', bottomPlayer.id)}
                                  isPlayable={isPlayable}
                                  isSelected={isSelected}
                                  isDragging={dragState?.cardId === c.id}
                               />
                           </div>
                       );
                   })}
               </div>
          </div>

          <div className="w-64 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3 shrink-0">
              <div className="text-center text-xs font-bold text-slate-500 uppercase mb-2">Actions</div>
              <div className={`flex-1 grid grid-cols-2 gap-2 content-start ${!isInteractive ? 'pointer-events-none opacity-50 grayscale' : ''}`}>
                  {gameState.phase === Phase.INIT_SELECT && (
                      <button 
                         id="btn-confirm-init"
                         disabled={gameState.initSelectedIds.length !== 3}
                         onClick={handleConfirmInitSelection} 
                         className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg h-12"
                      >
                          Confirm ({gameState.initSelectedIds.length}/3)
                      </button>
                  )}
                  {/* ... (Rest of actions mostly same, slight rendering tweaks if needed) ... */}
                  {gameState.phase === Phase.RESOURCE_START && (
                      <>
                        <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <ArrowUpCircle size={20} className="mb-1"/> Add & Draw
                        </button>
                        <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95">
                            <RotateCcw size={20} className="mb-1"/> Swap Res
                        </button>
                      </>
                  )}
                  {(gameState.phase === Phase.RESOURCE_ADD_SELECT || gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND || gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE) && (
                      <>
                          <div className={`col-span-2 text-center text-xs font-bold flex items-center justify-center border rounded h-10 ${gameState.phase.includes('ADD') ? 'text-emerald-400 border-emerald-900 bg-emerald-900/20' : 'text-amber-400 border-amber-900 bg-amber-900/20'} animate-pulse`}>
                              {gameState.phase === Phase.RESOURCE_ADD_SELECT ? 'Select card to Add' : 'Select card to Swap'}
                          </div>
                          <button onClick={cancelResourceAction} className="col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10">
                              Cancel
                          </button>
                      </>
                  )}
                  {gameState.phase === Phase.MAIN && (
                      <>
                        <button 
                            disabled={bottomPlayer.hasAttackedThisTurn}
                            onClick={() => advancePhase(Phase.ATTACK_DECLARE)}
                            className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2 h-10 transition-transform active:scale-95"
                        >
                            <Sword size={18} /> Attack Phase
                        </button>
                        <button 
                            id="btn-end-turn"
                            onClick={requestEndTurn}
                            className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 ${isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}
                  {gameState.phase === Phase.ATTACK_DECLARE && (
                      <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12">
                          Confirm Attackers
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === 0 && (
                      <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">
                          Confirm Blocks
                      </button>
                  )}

                  {/* CPU Turn Indicator */}
                  {gameState.players[activeDecisionPlayerId].isCpu && gameState.phase !== Phase.INIT_SELECT && (
                      <div className="col-span-2 flex flex-col items-center justify-center h-full gap-2">
                          <div className="w-6 h-6 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                          <span className="text-xs text-indigo-400 font-bold animate-pulse">CPU Thinking...</span>
                      </div>
                  )}
              </div>
          </div>
      </div>

      <div className="absolute top-20 left-4 w-72 z-40 bottom-60 overflow-y-auto space-y-1 pointer-events-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent flex flex-col-reverse">
          {gameState.logs.map((log) => (
              <LogEntry key={log.id} text={log.text} />
          ))}
      </div>
      </>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Phase, GameState, PlayerState, Card, FieldCard, GameMode, Color, DragState, FlyingText, FlyingCard, Rank, LogEntry as LogEntryType, TutorialStep } from './types';
import { createDeck, getEffectiveColor, canBlock, generateId, createFieldCard, sortHand, getCpuInitSelection, getCpuResourceDecision, getBestMainPhaseAction, getCpuAttackers, getCpuBlocks, createTutorialDeck, TUTORIAL_LESSONS } from './utils';
import { INITIAL_LIFE, MAX_RESOURCES } from './constants';
import { CardDisplay } from './components/CardDisplay';
import { ArrowUpCircle, Sword, RotateCcw, Heart, Menu, LogOut, Play, Settings, ArrowRight, Trash2, X, Edit3, Cpu, Users, GraduationCap } from 'lucide-react';

// Imported Components
import { LogRenderer } from './components/ui/LogRenderer';
import { CoinFlipOverlay } from './components/overlays/CoinFlipOverlay';
import { TurnChangeOverlay } from './components/overlays/TurnChangeOverlay';
import { TutorialOverlay } from './components/overlays/TutorialOverlay';
import { Confetti, Explosion, DamageOverlay } from './components/effects/VisualEffects';
import { Flyer, SpecialCardAnimation } from './components/effects/GameAnimations';
import { MainMenu } from './components/screens/MainMenu';
import { SandboxTools } from './components/tools/SandboxTools';

interface DamageAnimInstance {
    id: string;
    val: number;
    playerId: number;
}

// Log Item with animation for "pushing up"
const LogEntry: React.FC<{ text: string }> = ({ text }) => {
    const [visible, setVisible] = useState(false);
    useEffect(() => {
        // Trigger animation after mount
        const t = setTimeout(() => setVisible(true), 10);
        return () => clearTimeout(t);
    }, []);

    return (
        <div className={`transition-all duration-300 ease-out origin-bottom ${visible ? 'max-h-20 opacity-100 mb-2 transform scale-100' : 'max-h-0 opacity-0 mb-0 transform scale-95'}`}>
             <div className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur">
                  <LogRenderer text={text} />
             </div>
        </div>
    );
};

export const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [autoSort, setAutoSort] = useState(true);

  // Menu State
  const [menuStep, setMenuStep] = useState<'MODE' | 'PLAYERS' | 'TUTORIAL_MENU'>('MODE');
  const [selectedMode, setSelectedMode] = useState<GameMode | null>(null);
  const [isCoinFlipping, setIsCoinFlipping] = useState(false);

  const [showEndTurnModal, setShowEndTurnModal] = useState(false);
  const [showResignModal, setShowResignModal] = useState(false);
  const [showQuitModal, setShowQuitModal] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [viewingDiscard, setViewingDiscard] = useState<'SHARED' | number | null>(null);
  const [isMobile, setIsMobile] = useState(false);
  const [showMobileLog, setShowMobileLog] = useState(false);

  // Gameplay State
  const [showTurnAnim, setShowTurnAnim] = useState(false);

  // Sandbox State
  const [sandboxToolsOpen, setSandboxToolsOpen] = useState(false);
  const [sandboxSearchTerm, setSandboxSearchTerm] = useState("");
  const [sandboxTargetPlayer, setSandboxTargetPlayer] = useState<0 | 1>(0);
  const [selectedSandboxCard, setSelectedSandboxCard] = useState<Card | null>(null);
  const [cardActionTarget, setCardActionTarget] = useState<{card: Card, loc: string, ownerId: number, instanceId?: string} | null>(null);
  const [showPlaySetup, setShowPlaySetup] = useState(false);

  const [dragState, setDragState] = useState<DragState | null>(null);
  const [specialAnim, setSpecialAnim] = useState<{ type: 'K'|'Q'|'J', card: Card, targetRect?: DOMRect } | null>(null);

  const [flyingTexts, setFlyingTexts] = useState<FlyingText[]>([]);
  const [flyingCards, setFlyingCards] = useState<FlyingCard[]>([]);

  // Changed to array to allow overlapping animations
  const [damageAnims, setDamageAnims] = useState<DamageAnimInstance[]>([]);

  const [explosions, setExplosions] = useState<{ id: string, x: number, y: number }[]>([]);

  const gameStateRef = useRef<GameState | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const lifeIconRef = useRef<HTMLDivElement>(null); // Top Player (or generic P2 on mobile)
  const bottomLifeRef = useRef<HTMLDivElement>(null); // Bottom Player (or generic P1 on mobile)

  // Refs for deck locations (named generically top/bottom)
  const bottomDeckRef = useRef<HTMLDivElement>(null);
  const topDeckRef = useRef<HTMLDivElement>(null);

  const handRef = useRef<HTMLDivElement>(null);
  const cpuHandRef = useRef<HTMLDivElement>(null);
  const isDrawingInitialRef = useRef(false);

  useEffect(() => { gameStateRef.current = gameState; }, [gameState]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const addLog = (prev: GameState, message: string): LogEntryType[] => {
    return [{ id: generateId(), text: message }, ...prev.logs];
  };

  const startGame = useCallback((
      mode: GameMode, 
      cpuConfig: { p1: boolean, p2: boolean }, 
      tutorialConfig?: { steps: TutorialStep[], setup?: (gameState: GameState) => void }
  ) => {
    // Reset Modal States
    setShowQuitModal(false);
    setShowResignModal(false);
    setShowMenu(false);
    setShowEndTurnModal(false);

    // 1. Setup Data
    let sharedDeck = [];
    if (mode === 'STREET') sharedDeck = createDeck();
    else if (mode === 'TUTORIAL') sharedDeck = createTutorialDeck();

    const createPlayer = (id: number, name: string, isCpu: boolean): PlayerState => {
      return {
        id,
        name,
        isCpu,
        life: INITIAL_LIFE,
        hand: [], 
        library: mode === 'PRO' ? createDeck() : [],
        resources: [],
        field: [],
        discard: [],
        consecutiveDrawFailures: 0,
        hasAttackedThisTurn: false
      };
    };

    const p1 = createPlayer(0, cpuConfig.p1 ? "CPU 1" : "Player 1", cpuConfig.p1);
    const p2 = createPlayer(1, cpuConfig.p2 ? "CPU 2" : "Player 2", cpuConfig.p2);

    const initialState: GameState = {
      mode,
      deck: sharedDeck,
      players: [p1, p2],
      turnPlayer: 0, 
      startingPlayerId: 0, // Placeholder, set by coin flip
      phase: mode === 'SANDBOX' ? Phase.MAIN : Phase.INIT_SELECT,
      turnCount: 1,
      pendingAttackers: [],
      pendingBlocks: {},
      selectedCardId: null,
      activeCombatCardId: null,
      initSelectedIds: [],
      targetMode: 'NONE',
      sourceCardId: null,
      winner: null,
      recentDamage: {},
      logs: [{ id: generateId(), text: `Game Started. Mode: ${mode}.` }],
      tutorialState: mode === 'TUTORIAL' && tutorialConfig ? {
          active: true,
          currentStepIndex: 0,
          steps: tutorialConfig.steps
      } : undefined
    };

    // Apply specific tutorial setup if provided
    if (mode === 'TUTORIAL' && tutorialConfig?.setup) {
        tutorialConfig.setup(initialState);
    }

    if (mode === 'SANDBOX') {
        setGameState(initialState);
        setMenuStep('MODE');
        setIsCoinFlipping(false);
        setShowMenu(false);
        setSandboxToolsOpen(true);
    } else if (mode === 'TUTORIAL') {
        setGameState(initialState);
        setMenuStep('MODE');
        setIsCoinFlipping(false); // No coin flip in tutorial
        setShowMenu(false);
    } else {
        setGameState(initialState);
        setMenuStep('MODE'); 
        setIsCoinFlipping(true);
        setShowMenu(false); 
    }

  }, [autoSort]);

  // Initial Draw Effect
  useEffect(() => {
    if (gameState && gameState.mode !== 'SANDBOX' && gameState.phase === Phase.INIT_SELECT && !isCoinFlipping) {
      if (!isDrawingInitialRef.current) {
        const p1 = gameState.players[0];
        const p2 = gameState.players[1];

        if (p1.hand.length === 0 || p2.hand.length === 0) {
             isDrawingInitialRef.current = true;
             (async () => {
                 await drawCards(0, 8);
                 await drawCards(1, 8);
                 setGameState(prev => prev ? { ...prev, logs: addLog(prev, "Deployment Phase: Select 3 resources.") } : null);
                 isDrawingInitialRef.current = false;
             })();
        }
      }
    }
  }, [gameState?.phase, isCoinFlipping, gameState?.mode]);

  // Tutorial Step Advancement Logic
  const advanceTutorialStep = (actionType: 'CLICK_CARD' | 'CLICK_UI_BUTTON' | 'PLAY_CARD' | 'PHASE_CHANGE' | 'NEXT', targetId?: string) => {
      setGameState(prev => {
          if (!prev || !prev.tutorialState || !prev.tutorialState.active) return prev;

          const step = prev.tutorialState.steps[prev.tutorialState.currentStepIndex];
          if (!step) return prev;

          // Check Requirements (Check specific requirement if strict)
          if (step.requiredAction !== 'NONE') {
               if (step.requiredAction !== actionType) return prev;
               if (step.targetId && step.targetId !== targetId) return prev;
          }

          // Advance
          const nextIndex = prev.tutorialState.currentStepIndex + 1;
          if (nextIndex < prev.tutorialState.steps.length) {
              return {
                  ...prev,
                  tutorialState: {
                      ...prev.tutorialState,
                      currentStepIndex: nextIndex
                  }
              };
          } else {
              // End Tutorial
              return {
                  ...prev,
                  tutorialState: { ...prev.tutorialState, active: false, completed: true },
                  logs: addLog(prev, "Lesson Complete!")
              };
          }
      });
  };

  // Helper for Passive Tutorial Steps (click to advance)
  const handleGlobalClick = () => {
      if (gameState?.tutorialState?.active) {
          const step = gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex];
          if (step.requiredAction === 'NONE') {
              advanceTutorialStep('NONE' as any);
          }
      }
  };

  const isInteractionAllowed = (interactionId: string): boolean => {
      const state = gameStateRef.current;
      if (!state || state.mode !== 'TUTORIAL' || !state.tutorialState || !state.tutorialState.active) {
          return true; // Not in tutorial mode, everything allowed
      }

      const step = state.tutorialState.steps[state.tutorialState.currentStepIndex];
      // If action is NONE or NEXT, block everything except overlay (which is handled separately)
      if (step.requiredAction === 'NONE' || step.requiredAction === 'NEXT') return false; 

      return step ? step.allowedInteractionIds.includes(interactionId) : false;
  };

  const getActiveDecisionPlayerId = (state: GameState): number => {
      if (state.mode === 'SANDBOX') {
          if (state.isSandboxRun) return state.turnPlayer;
          return state.turnPlayer; 
      }
      if (state.phase === Phase.INIT_SELECT && state.players[1].isCpu && !state.players[0].isCpu) {
          // Classic P1 setup vs CPU case
          return 0;
      }
      if (state.phase === Phase.BLOCK_DECLARE) return state.turnPlayer === 0 ? 1 : 0;
      return state.turnPlayer;
  };

  useEffect(() => {
      // Pause CPU if menu is open or turn animation is playing
      if (showMenu || showTurnAnim || !gameState || gameState.phase === Phase.GAME_OVER || isCoinFlipping) return;
      if (gameState.mode === 'SANDBOX' && !gameState.isSandboxRun) return; 

      const activePlayerId = getActiveDecisionPlayerId(gameState);
      const activePlayer = gameState.players[activePlayerId];

      // If active player is CPU, execute turn
      if (activePlayer.isCpu) {
          // Variable thinking time: 1.5s to 3s
          const thinkTime = 1500 + Math.random() * 1500;
          const timer = setTimeout(async () => { await executeCpuTurn(); }, thinkTime); 
          return () => clearTimeout(timer);
      }
  }, [gameState?.phase, gameState?.turnPlayer, gameState?.turnCount, gameState?.players, isCoinFlipping, gameState?.mode, gameState?.isSandboxRun, showMenu, showTurnAnim]);

  const executeCpuTurn = async () => {
      const state = gameStateRef.current;
      if (!state) return;
      const activePlayerId = getActiveDecisionPlayerId(state);
      const cpu = state.players[activePlayerId];

      switch(state.phase) {
          case Phase.INIT_SELECT:
              // Setup Phase CPU Logic
              if (state.initSelectedIds.length === 0) {
                  const cpuIds = getCpuInitSelection(cpu.hand);
                  // Simulate Selection
                  setGameState(prev => {
                      if(!prev) return null;
                      return { ...prev, initSelectedIds: cpuIds };
                  });
                  await new Promise(r => setTimeout(r, 800));
                  handleConfirmInitSelection();
              }
              break;
          case Phase.RESOURCE_START:
              const resDecision = getCpuResourceDecision(cpu, state.turnCount);
              if (resDecision.action === 'SKIP') {
                  advancePhase(Phase.MAIN);
              } else if (resDecision.action === 'ADD' && resDecision.cardIdToAdd) {
                  const card = cpu.hand.find(c => c.id === resDecision.cardIdToAdd);
                  if (card) {
                      advancePhase(Phase.RESOURCE_ADD_SELECT);
                      await new Promise(r => setTimeout(r, 500));
                      await handleCardClick(card, 'HAND', activePlayerId, undefined, true);
                  }
              } else if (resDecision.action === 'SWAP') { advancePhase(Phase.MAIN); }
              break;
          case Phase.MAIN:
              const action = getBestMainPhaseAction(state);
              if (action.type === 'END_TURN') {
                  const possibleAttackers = getCpuAttackers(state);
                  if (!cpu.hasAttackedThisTurn && possibleAttackers.length > 0) { advancePhase(Phase.ATTACK_DECLARE); } 
                  else { performEndTurn(); }
              } 
              else if (action.type === 'PLAY_UNIT' && action.cardId) {
                  const card = cpu.hand.find(c => c.id === action.cardId);
                  if(card) playCardImmediate(card); 
              }
              else if (action.type === 'PLAY_TACTIC' && action.cardId) {
                  const card = cpu.hand.find(c => c.id === action.cardId);
                  if (card) {
                      // Fix: Correctly identify the target owner. The utils function returns an instanceId.
                      let targetOwnerId = 0; // Default
                      if (action.targetId) {
                          const opponentId = activePlayerId === 0 ? 1 : 0;
                          // Check opponent first (most likely)
                          if (state.players[opponentId].field.some(f => f.instanceId === action.targetId)) {
                              targetOwnerId = opponentId;
                          } else if (state.players[activePlayerId].field.some(f => f.instanceId === action.targetId)) {
                              targetOwnerId = activePlayerId;
                          }
                      }
                      playCardImmediate(card, action.targetId, targetOwnerId);
                  }
              }
              break;
          case Phase.ATTACK_DECLARE:
              const attackerIds = getCpuAttackers(state);
              if (attackerIds.length > 0) {
                  setGameState(prev => ({ ...prev!, pendingAttackers: attackerIds }));
                  await new Promise(r => setTimeout(r, 500));
                  confirmAttack();
              } else { advancePhase(Phase.MAIN); }
              break;
          case Phase.BLOCK_DECLARE:
              // For blocks, activePlayerId is the Defender
              const blocks = getCpuBlocks(state, activePlayerId);
              setGameState(prev => ({ ...prev!, pendingBlocks: blocks }));
              await new Promise(r => setTimeout(r, 500));
              confirmBlocks();
              break;
      }
  };

  const formatCardLog = (card: Card) => `[${card.rank}${card.suit}]`;

  const canDoAnything = (state: GameState): boolean => {
      const pId = state.turnPlayer;
      const player = state.players[pId];
      if (state.phase !== Phase.MAIN) return false;
      const availableRes = player.resources.filter(r => !r.isTapped).length;
      const canPlayCard = player.hand.some(c => c.cost <= availableRes);
      const canAttack = !player.hasAttackedThisTurn && player.field.some(c => !c.isTapped && !c.isSummoningSick);
      return canPlayCard || canAttack;
  };

  // ... (Utils like triggerFlyer, triggerExplosion, drawCards, etc. preserved) ...
  const triggerFlyer = async (card: Card, startRect: DOMRect, targetRect: DOMRect): Promise<void> => {
      return new Promise(resolve => {
          const id = generateId();
          const newFly: FlyingCard = {
              id, card, startX: startRect.left, startY: startRect.top, targetX: targetRect.left + targetRect.width / 2 - 20, targetY: targetRect.top + targetRect.height / 2 - 30, createdAt: Date.now()
          };
          setFlyingCards(prev => [...prev, newFly]);
          setTimeout(() => { setFlyingCards(prev => prev.filter(f => f.id !== id)); resolve(); }, 600);
      });
  };

  const triggerExplosion = (instanceId: string) => {
      const el = document.getElementById(instanceId);
      if (el) {
          const rect = el.getBoundingClientRect();
          setExplosions(prev => [...prev, { id: generateId(), x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }]);
      }
  };

  const drawCards = async (playerId: number, count: number) => {
      const startState = gameStateRef.current;
      if (!startState) return;
      const pIndex = startState.players.findIndex(p => p.id === playerId);
      // Logic for Spectate: We always render the board from P0 view, but actions happen for both
      const isHotseat = !startState.players[1].isCpu || startState.players[0].isCpu; // Treat Spectate like hotseat for rendering purposes? 
      // Actually, if Spectate, we might just keep P0 at bottom.
      const isSpectate = startState.players[0].isCpu && startState.players[1].isCpu;

      const viewId = (isHotseat && !isSpectate) ? startState.turnPlayer : 0;
      const isBottom = playerId === viewId;

      const deck = startState.mode === 'STREET' || startState.mode === 'TUTORIAL' ? startState.deck : startState.players[pIndex].library;
      const availableCount = deck.length;
      const cardsToDraw = deck.slice(0, Math.min(count, availableCount));
      const failuresNeeded = count - cardsToDraw.length;

      for (const card of cardsToDraw) {
           let startRect = isBottom ? bottomDeckRef.current?.getBoundingClientRect() : topDeckRef.current?.getBoundingClientRect();
           let targetRect = isBottom ? handRef.current?.getBoundingClientRect() : cpuHandRef.current?.getBoundingClientRect();

           // Fallback for spectate if animating the 'top' player (P1)
           if (isSpectate && playerId === 1) {
               startRect = topDeckRef.current?.getBoundingClientRect();
               targetRect = cpuHandRef.current?.getBoundingClientRect();
           }

           if (startRect && targetRect) { triggerFlyer(card, startRect, targetRect); }

           setGameState(prev => {
               if (!prev) return null;
               const nextPlayers = [...prev.players];
               const nextP = { ...nextPlayers[pIndex] };
               let nextDeck = prev.deck;
               if (prev.mode === 'STREET' || prev.mode === 'TUTORIAL') { nextDeck = prev.deck.filter(c => c.id !== card.id); } 
               else { nextP.library = nextP.library.filter(c => c.id !== card.id); }
               nextP.hand = [...nextP.hand, card];
               if (autoSort) nextP.hand = sortHand(nextP.hand);
               nextPlayers[pIndex] = nextP;
               return { ...prev, deck: prev.mode === 'STREET' || prev.mode === 'TUTORIAL' ? nextDeck : prev.deck, players: nextPlayers };
           });
           await new Promise(r => setTimeout(r, 60));
      }
      if (cardsToDraw.length > 0) { setGameState(prev => prev ? { ...prev, logs: addLog(prev, `${startState.players[pIndex].name} drew ${cardsToDraw.length} cards.`) } : null); }
      if (failuresNeeded > 0) {
          setGameState(prev => {
               if (!prev) return null;
               const nextPlayers = prev.players.map(pl => pl.id === playerId ? { ...pl, consecutiveDrawFailures: pl.consecutiveDrawFailures + failuresNeeded } : pl);
               return { ...prev, players: nextPlayers, logs: addLog(prev, "Deck Empty!") };
          });
          setTimeout(() => { if (gameStateRef.current) checkGameOver(gameStateRef.current); }, 100);
      }
  };

  const handleResign = () => {
      if (!gameState) return;
      setGameState(prev => {
          if(!prev) return null;
          const activePid = getActiveDecisionPlayerId(prev);
          const opponentId = activePid === 0 ? 1 : 0;
          return { ...prev, winner: opponentId, phase: Phase.GAME_OVER, logs: addLog(prev, `${prev.players[activePid].name} resigned.`) };
      });
      setShowResignModal(false); setShowMenu(false);
  };

  const toggleAutoSort = () => {
      setAutoSort(prev => !prev);
      setGameState(prev => {
          if(!prev) return null;
          if (!autoSort) { 
             const activePid = getActiveDecisionPlayerId(prev);
             const nextPlayers = [...prev.players];
             nextPlayers[activePid].hand = sortHand(nextPlayers[activePid].hand);
             return { ...prev, players: nextPlayers };
          }
          return prev;
      });
  };

  const advancePhase = (targetPhase: Phase, overrideState?: GameState) => {
    setGameState(prev => {
      if (!prev && !overrideState) return null;
      let newState = overrideState ? { ...overrideState } : { ...prev! };
      newState.phase = targetPhase;
      const player = newState.players[newState.turnPlayer];

      switch (targetPhase) {
        case Phase.UPKEEP:
          newState.players.forEach(p => {
             if (p.id === newState.turnPlayer) {
                 p.field.forEach(c => { c.isTapped = false; c.isSummoningSick = false; });
                 p.resources.forEach(r => r.isTapped = false);
             }
          });
          newState.pendingAttackers = []; newState.pendingBlocks = {}; newState.selectedCardId = null; newState.recentDamage = {}; newState.activeCombatCardId = null;
          player.hasAttackedThisTurn = false;
          newState.logs = addLog(newState, `Turn ${newState.turnCount}: ${player.name}'s Upkeep.`);
          setTimeout(() => advancePhase(Phase.DRAW), 800);
          break;
        case Phase.DRAW:
            setTimeout(() => {
                drawCards(player.id, 1).then(() => {
                     setGameState(current => {
                         if(!current) return null;
                         const p = current.players[current.turnPlayer];
                         const isTurn1FirstPlayer = current.turnCount === 1 && current.turnPlayer === current.startingPlayerId;
                         const hasMaxResources = p.resources.length >= MAX_RESOURCES;
                         if (isTurn1FirstPlayer || hasMaxResources) {
                            setTimeout(() => advancePhase(Phase.MAIN), 400);
                            return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, isTurn1FirstPlayer ? "Turn 1: Resource Step skipped." : "Max Resources reached.") };
                         } else { return { ...current, phase: Phase.RESOURCE_START, logs: addLog(current, "Resource Step.") }; }
                     });
                });
            }, 0);
            break;
        case Phase.RESOURCE_START: break;
        case Phase.MAIN: newState.logs = addLog(newState, "Main Phase."); break;
        case Phase.ATTACK_DECLARE: newState.logs = addLog(newState, "Declare Attackers."); break;
        case Phase.BLOCK_DECLARE:
             const defender = newState.players[newState.turnPlayer === 0 ? 1 : 0];
             newState.logs = addLog(newState, `${defender.name} declares blocks.`);
             break;
      }
      return newState;
    });

    // Tutorial Check
    if (gameState?.tutorialState?.active) {
        setTimeout(() => advanceTutorialStep('PHASE_CHANGE'), 100);
    }
  };

  const confirmAttack = () => {
      setGameState(prev => {
          if(!prev) return null;
          if (prev.pendingAttackers.length === 0) return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "No attacks declared.") };
          const p = prev.players[prev.turnPlayer];
          const attackers = p.field.filter(f => prev.pendingAttackers.includes(f.instanceId));
          const attackerNames = attackers.map(f => formatCardLog(f.card)).join(', ');
          p.field.forEach(f => { if (prev.pendingAttackers.includes(f.instanceId)) f.isTapped = true; });
          p.hasAttackedThisTurn = true;
          const defender = prev.players[prev.turnPlayer === 0 ? 1 : 0];
          const attackingColors = new Set(attackers.map(getEffectiveColor));
          const untappedDefenders = defender.field.filter(f => !f.isTapped);
          const canDefend = untappedDefenders.some(def => attackingColors.has(getEffectiveColor(def)));
          if (!canDefend) return { ...prev, phase: Phase.DAMAGE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}. Direct Hit!`) };
          return { ...prev, phase: Phase.BLOCK_DECLARE, logs: addLog(prev, `${p.name} attacks with ${attackerNames}.`) };
      });
  };

  const confirmBlocks = () => { setGameState(prev => prev ? { ...prev, phase: Phase.DAMAGE } : null); };
  const requestEndTurn = () => { 
      if (!isInteractionAllowed('btn-end-turn')) return;
      setShowEndTurnModal(true); 
  };
  const performEndTurn = () => {
    setGameState(prev => {
        if(!prev) return null;
        const nextPlayerIdx = prev.turnPlayer === 0 ? 1 : 0;
        const nextTurnCount = nextPlayerIdx === 0 ? prev.turnCount + 1 : prev.turnCount;
        const nextState = { ...prev, turnPlayer: nextPlayerIdx, turnCount: nextTurnCount, phase: Phase.UPKEEP };
        setTimeout(() => advancePhase(Phase.UPKEEP, nextState), 0);
        return nextState; 
    });
    // Trigger interstitial animation
    setShowTurnAnim(true);
  };
  const confirmEndTurn = () => { setShowEndTurnModal(false); performEndTurn(); };

  useEffect(() => { if (gameState?.phase === Phase.DAMAGE) executeCombatSequence(); }, [gameState?.phase]);

  const executeCombatSequence = async () => {
      const getLatest = () => gameStateRef.current!;
      let state = getLatest();
      const attackerPlayer = state.players[state.turnPlayer];
      const defenderPlayer = state.players[state.turnPlayer === 0 ? 1 : 0];
      const attackers = attackerPlayer.field.filter(f => state.pendingAttackers.includes(f.instanceId));
      const directAttackers = attackers.filter(atk => !Object.values(state.pendingBlocks).includes(atk.instanceId));

      const delayPre = 100;
      const delayPost = 300; // Small delay between attacks

      // 1. Process Blocked Combats
      for (const atk of attackers) {
          const blockerId = Object.keys(state.pendingBlocks).find(k => state.pendingBlocks[k] === atk.instanceId);
          if (blockerId) {
                setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
                await new Promise(r => setTimeout(r, 400));
                setGameState(prev => {
                    if (!prev) return null;
                    const blk = defenderPlayer.field.find(f => f.instanceId === blockerId);
                    if (!blk) return prev;
                    const nextRecentDamage = { ...prev.recentDamage };
                    nextRecentDamage[atk.instanceId] = blk.card.numericValue;
                    nextRecentDamage[blk.instanceId] = atk.card.numericValue;
                    const logMsg = `⚔️ Battle: ${formatCardLog(atk.card)} (${atk.card.numericValue}) vs ${formatCardLog(blk.card)} (${blk.card.numericValue})`;
                    return { ...prev, recentDamage: nextRecentDamage, logs: addLog(prev, logMsg) };
                });
                await new Promise(r => setTimeout(r, 600)); 
                setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
                await new Promise(r => setTimeout(r, 100));
          }
      }

      // 2. Process Direct Attacks
      for (const atk of directAttackers) {
           setGameState(prev => prev ? { ...prev, activeCombatCardId: atk.instanceId } : null);
           await new Promise(r => setTimeout(r, delayPre));

           const dmg = atk.card.rank === 'A' ? 1 : atk.card.numericValue;
           // Push new animation (component handles lifecycle)
           setDamageAnims(prev => [...prev, { id: generateId(), val: dmg, playerId: defenderPlayer.id }]);

           setGameState(prev => {
               if(!prev) return null;
               // Log only, update life later in state
               const nextPlayers = [...prev.players];
               const defIdx = nextPlayers.findIndex(p => p.id === defenderPlayer.id);
               if (defIdx > -1) { nextPlayers[defIdx] = { ...nextPlayers[defIdx], life: nextPlayers[defIdx].life - dmg }; }
               return { ...prev, players: nextPlayers, logs: addLog(prev, `🔥 Direct Hit! ${formatCardLog(atk.card)} deals ${dmg} damage.`) };
           });

           // Slight delay so they don't stack instantly
           await new Promise(r => setTimeout(r, delayPost));
           setGameState(prev => prev ? { ...prev, activeCombatCardId: null } : null);
      }

      // 3. Cleanup & Death
      setGameState(prev => {
          if (!prev) return null;
          const nextState = { ...prev };
          const atkP = nextState.players[nextState.turnPlayer];
          const defP = nextState.players[nextState.turnPlayer === 0 ? 1 : 0];
          const activeAtk = atkP.field.filter(f => nextState.pendingAttackers.includes(f.instanceId));

          activeAtk.forEach(atk => {
              const blockerId = Object.keys(nextState.pendingBlocks).find(k => nextState.pendingBlocks[k] === atk.instanceId);
              if (blockerId) {
                  const blk = defP.field.find(f => f.instanceId === blockerId);
                  if (blk) {
                      const atkVal = atk.card.numericValue; const blkVal = blk.card.numericValue;
                      const atkIsAce = atk.card.rank === 'A'; const blkIsAce = blk.card.rank === 'A';
                      let atkDies = false; let blkDies = false;
                      if (atkIsAce) blkDies = true; if (blkIsAce) atkDies = true;
                      if (!atkIsAce && !blkIsAce) {
                          if (atkVal > blkVal) blkDies = true; else if (blkVal > atkVal) atkDies = true; else { atkDies = true; blkDies = true; }
                      } else { if(atkIsAce && !blkIsAce) atkDies = true; if(blkIsAce && !atkIsAce) blkDies = true; }

                      if (atkDies) { triggerExplosion(atk.instanceId); atkP.field = atkP.field.filter(f => f.instanceId !== atk.instanceId); atkP.discard.push(atk.card, ...atk.attachedCards); }
                      if (blkDies) { triggerExplosion(blk.instanceId); defP.field = defP.field.filter(f => f.instanceId !== blk.instanceId); defP.discard.push(blk.card, ...blk.attachedCards); }
                  }
              } 
          });
          nextState.recentDamage = {}; nextState.pendingAttackers = []; nextState.pendingBlocks = {}; nextState.phase = Phase.MAIN;
          if (defP.life <= 0) nextState.winner = atkP.id;
          if (atkP.life <= 0) nextState.winner = defP.id;
          if (nextState.winner !== null) nextState.phase = Phase.GAME_OVER;
          return nextState;
      });
  };

  const handleModeSelect = (mode: GameMode) => {
      if (mode === 'SANDBOX') { startGame('SANDBOX', { p1: false, p2: false }); } 
      else if (mode === 'TUTORIAL') { 
          // Switch to Tutorial Submenu instead of starting immediately
          setMenuStep('TUTORIAL_MENU');
      }
      else { setSelectedMode(mode); setMenuStep('PLAYERS'); }
  };

  const startLesson = (lessonId: string) => {
      const lesson = TUTORIAL_LESSONS.find(l => l.id === lessonId);
      if (lesson) {
          // Pass the lesson config object (steps + setup) to startGame
          startGame('TUTORIAL', { p1: false, p2: true }, { steps: lesson.steps, setup: lesson.setup });
      }
  };

  const handleStartGameClick = (isCpu: boolean) => {
      if (selectedMode) { startGame(selectedMode, { p1: false, p2: isCpu }); }
  };

  const handleSpectateClick = () => {
      if (selectedMode) { startGame(selectedMode, { p1: true, p2: true }); }
  };

  const getPhaseName = () => {
    if (!gameState) return '';
    switch (gameState.phase) {
      case Phase.INIT_SELECT: return 'Deployment';
      case Phase.UPKEEP: return 'Upkeep';
      case Phase.DRAW: return 'Draw Step';
      case Phase.RESOURCE_START: return 'Resource Step';
      case Phase.RESOURCE_ADD_SELECT: return 'Select Resource';
      case Phase.RESOURCE_SWAP_SELECT_HAND: return 'Swap: Hand Card';
      case Phase.RESOURCE_SWAP_SELECT_PILE: return 'Swap: Resource';
      case Phase.MAIN: return 'Main Phase';
      case Phase.ATTACK_DECLARE: return 'Declare Attackers';
      case Phase.BLOCK_DECLARE: return 'Declare Blockers';
      case Phase.DAMAGE: return 'Combat Damage';
      case Phase.GAME_OVER: return 'Game Over';
      default: return '';
    }
  };

  const handleQuitToTitle = () => {
      setGameState(null);
      setShowQuitModal(false);
      setShowResignModal(false);
      setShowEndTurnModal(false);
      setShowMenu(false);
      setMenuStep('MODE');
  };

  const handleTurnAnimComplete = () => {
      setShowTurnAnim(false);
  };

  const checkGameOver = (state: GameState) => {
      if (state.phase === Phase.GAME_OVER) return;
      let winner = null;
      if (state.players[0].life <= 0 && state.players[1].life <= 0) winner = null; // Draw
      else if (state.players[0].life <= 0) winner = 1;
      else if (state.players[1].life <= 0) winner = 0;

      if (winner !== null || (state.players[0].life <= 0 && state.players[1].life <= 0)) {
          setGameState(prev => prev ? { ...prev, winner, phase: Phase.GAME_OVER, logs: addLog(prev, "Game Over!") } : null);
      }
  };

  // Drag and Drop
  const handleDragStart = (e: React.MouseEvent, card: Card, sourceType: 'HAND' | 'FIELD', ownerId: number, instanceId?: string) => {
      if (!isInteractionAllowed(card.id)) return;
      if (gameState?.phase !== Phase.MAIN && gameState?.phase !== Phase.ATTACK_DECLARE) return;

      // Only allow dragging own cards
      const activePid = getActiveDecisionPlayerId(gameState!);
      if (ownerId !== activePid) return;
      if (gameState!.players[activePid].isCpu) return;

      setDragState({
          cardId: card.id,
          sourceType,
          ownerId,
          startX: e.clientX,
          startY: e.clientY,
          currentX: e.clientX,
          currentY: e.clientY,
          cardObj: card,
          instanceId
      });
  };

  const handleDrop = (e: MouseEvent, drag: DragState) => {
      // Check if dropped on field area
      const fieldArea = document.getElementById('field-area');
      if (fieldArea) {
          const rect = fieldArea.getBoundingClientRect();
          if (e.clientX >= rect.left && e.clientX <= rect.right && e.clientY >= rect.top && e.clientY <= rect.bottom) {
               if (drag.sourceType === 'HAND') {
                   // Try to play card
                   handleCardClick(drag.cardObj!, 'HAND', drag.ownerId);
               }
          }
      }
  };

  const playCardImmediate = async (card: Card, targetId?: string, targetOwnerId?: number) => {
        setGameState(prev => {
            if (!prev) return null;
            const p = prev.players[prev.turnPlayer];

            // 1. Pay Costs
            const availableRes = p.resources.filter(r => !r.isTapped);
            if (availableRes.length < card.cost) return prev; // Should be checked before

            // Auto-tap resources (naive: first N available)
            let costRemaining = card.cost;
            for (const r of p.resources) {
                if (!r.isTapped && costRemaining > 0) {
                    r.isTapped = true;
                    costRemaining--;
                }
            }

            // 2. Remove from Hand
            p.hand = p.hand.filter(c => c.id !== card.id);

            // 3. Effect or Field
            if (['J', 'Q', 'K'].includes(card.rank)) {
                // Tactic Logic handled via logging here, effect below
            } else {
                // Unit
                const newFieldCard = createFieldCard(card, p.id);
                p.field.push(newFieldCard);
            }

            return { ...prev, logs: addLog(prev, `${p.name} played ${card.rank}${card.suit}.`) };
        });

        // Handle Side Effects (Draw, Animations)
        if (['J', 'Q', 'K'].includes(card.rank)) {
             setSpecialAnim({ type: card.rank as any, card });
             await new Promise(r => setTimeout(r, 800)); // Wait for anim

             if (card.rank === 'J') {
                 await drawCards(gameStateRef.current!.turnPlayer, 2);
             } else if (card.rank === 'K' && targetId) {
                  // Destroy target
                  setGameState(prev => {
                      if(!prev) return null;
                      const opponent = prev.players[targetOwnerId || 0];
                      const target = opponent.field.find(f => f.instanceId === targetId);
                      if (target) {
                           opponent.field = opponent.field.filter(f => f.instanceId !== targetId);
                           opponent.discard.push(target.card, ...target.attachedCards);
                           triggerExplosion(targetId);
                           return { ...prev, logs: addLog(prev, `King destroyed ${target.card.rank}${target.card.suit}!`) };
                      }
                      return prev;
                  });
             } else if (card.rank === 'Q' && targetId) {
                  // Shift target (Toggle Color)
                   setGameState(prev => {
                      if(!prev) return null;
                      // Target could be self or opponent
                      const targetOwner = prev.players.find(pl => pl.field.some(f => f.instanceId === targetId));
                      if (targetOwner) {
                          const target = targetOwner.field.find(f => f.instanceId === targetId);
                          if (target) {
                              target.attachedCards.push(card);
                              return { ...prev, logs: addLog(prev, `Queen shifted ${target.card.rank}${target.card.suit}!`) };
                          }
                      }
                      return prev;
                  });
             }

             // Discard the Tactic
             setGameState(prev => {
                 if(!prev) return null;
                 const p = prev.players[prev.turnPlayer];
                 p.discard.push(card);
                 return prev;
             });

        }

        // Tutorial Check
        if (gameStateRef.current?.tutorialState?.active) {
            advanceTutorialStep('PLAY_CARD', card.id);
        }
  };

  const handleCardClick = async (card: Card, location: 'HAND' | 'FIELD' | 'RESOURCE', ownerId: number, instanceId?: string, isCpuAction = false) => {
      if (!isInteractionAllowed(instanceId || card.id) && !isCpuAction) return;
      const state = gameStateRef.current;
      if (!state) return;

      const activePid = getActiveDecisionPlayerId(state);

      // INIT SELECT
      if (state.phase === Phase.INIT_SELECT && location === 'HAND' && ownerId === activePid) {
           if (state.initSelectedIds.includes(card.id)) {
               setGameState(prev => prev ? { ...prev, initSelectedIds: prev.initSelectedIds.filter(id => id !== card.id) } : null);
           } else if (state.initSelectedIds.length < 3) {
               setGameState(prev => prev ? { ...prev, initSelectedIds: [...prev.initSelectedIds, card.id] } : null);
           }
           return;
      }

      // RESOURCE STEPS
      if (state.phase === Phase.RESOURCE_ADD_SELECT && location === 'HAND' && ownerId === activePid) {
           // Move card to resources
           setGameState(prev => {
               if(!prev) return null;
               const p = prev.players[activePid];
               p.hand = p.hand.filter(c => c.id !== card.id);
               const fc = createFieldCard(card, activePid);
               fc.isSummoningSick = false;
               p.resources.push(fc);
               return { ...prev, phase: Phase.MAIN, logs: addLog(prev, "Resource added.") };
           });
           await drawCards(activePid, 1);
           return;
      }

      // MAIN PHASE PLAY
      if (state.phase === Phase.MAIN && location === 'HAND' && ownerId === activePid) {
           // Check playability
           const p = state.players[activePid];
           const available = p.resources.filter(r => !r.isTapped).length;
           if (card.cost > available) {
               setGameState(prev => prev ? { ...prev, logs: addLog(prev, "Not enough resources!") } : null);
               return;
           }

           // Tactic Handling (Targeting)
           if (['K', 'Q'].includes(card.rank)) {
               if (state.targetMode === 'NONE') {
                   // Enter Target Mode
                   setGameState(prev => prev ? { 
                       ...prev, 
                       targetMode: card.rank === 'K' ? 'KING' : 'QUEEN',
                       sourceCardId: card.id,
                       logs: addLog(prev, `Select target for ${card.rank}...`)
                   } : null);
               } else if (state.sourceCardId === card.id) {
                   // Cancel
                   setGameState(prev => prev ? { ...prev, targetMode: 'NONE', sourceCardId: null } : null);
               }
               return;
           }

           // Jack or Unit -> Immediate
           await playCardImmediate(card);
           return;
      }

      // TARGETING RESOLUTION (Clicking Field Cards)
      if (state.phase === Phase.MAIN && location === 'FIELD' && state.targetMode !== 'NONE') {
           const sourceCard = state.players[activePid].hand.find(c => c.id === state.sourceCardId);
           if (sourceCard && instanceId) {
               // Execute Tactic
               await playCardImmediate(sourceCard, instanceId, ownerId);
               setGameState(prev => prev ? { ...prev, targetMode: 'NONE', sourceCardId: null } : null);
           }
           return;
      }

      // ATTACK DECLARE
      if (state.phase === Phase.ATTACK_DECLARE && location === 'FIELD' && ownerId === activePid) {
          const fieldCard = state.players[activePid].field.find(f => f.instanceId === instanceId);
          if (fieldCard && !fieldCard.isTapped && !fieldCard.isSummoningSick) {
               setGameState(prev => {
                   if (!prev) return null;
                   const isDeclared = prev.pendingAttackers.includes(instanceId!);
                   if (isDeclared) {
                       return { ...prev, pendingAttackers: prev.pendingAttackers.filter(id => id !== instanceId) };
                   } else {
                       return { ...prev, pendingAttackers: [...prev.pendingAttackers, instanceId!] };
                   }
               });
          }
          return;
      }

      // BLOCK DECLARE
      if (state.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId === activePid) { // activePid is defender here
           if (state.selectedCardId === instanceId) {
               // Deselect
               setGameState(prev => prev ? { ...prev, selectedCardId: null } : null);
           } else {
               // Select Blocker
               setGameState(prev => prev ? { ...prev, selectedCardId: instanceId || null } : null);
           }
      }

      // If we have a selected Blocker, and we click an Attacker (Opponent's field card)
      if (state.phase === Phase.BLOCK_DECLARE && location === 'FIELD' && ownerId !== activePid && state.selectedCardId) {
           const blockerId = state.selectedCardId;
           const attackerId = instanceId;
           if (blockerId && attackerId && state.pendingAttackers.includes(attackerId)) {
               // Register Block
               setGameState(prev => {
                   if (!prev) return null;
                   // Validate colors
                   const defender = prev.players[activePid];
                   const attackerPlayer = prev.players[activePid === 0 ? 1 : 0];
                   const bCard = defender.field.find(f => f.instanceId === blockerId);
                   const aCard = attackerPlayer.field.find(f => f.instanceId === attackerId);

                   if (bCard && aCard && canBlock(aCard, bCard)) {
                       return { 
                           ...prev, 
                           pendingBlocks: { ...prev.pendingBlocks, [blockerId]: attackerId },
                           selectedCardId: null // Reset selection
                       };
                   } else {
                       return { ...prev, logs: addLog(prev, "Invalid Block: Colors must match.") };
                   }
               });
           }
      }
  };

  const handleConfirmInitSelection = () => {
      const state = gameStateRef.current;
      if (!state) return;
      const activePid = getActiveDecisionPlayerId(state);

      setGameState(prev => {
          if (!prev) return null;
          const p = prev.players[activePid];
          const selected = p.hand.filter(c => prev.initSelectedIds.includes(c.id));
          const kept = p.hand.filter(c => !prev.initSelectedIds.includes(c.id));

          const newResources = selected.map(c => {
             const fc = createFieldCard(c, activePid);
             fc.isSummoningSick = false;
             return fc;
          });

          const nextPlayers = [...prev.players];
          nextPlayers[activePid] = { ...p, hand: kept, resources: [...p.resources, ...newResources] };

          if (activePid === 0) {
              // P1 finished. Move to P2.
              return { ...prev, players: nextPlayers, initSelectedIds: [], turnPlayer: 1, logs: addLog(prev, `${p.name} deployed resources.`) };
          } else {
              // P2 finished. Start Game.
              return { 
                  ...prev, 
                  players: nextPlayers, 
                  initSelectedIds: [], 
                  turnPlayer: prev.startingPlayerId, 
                  phase: Phase.UPKEEP, 
                  turnCount: 1,
                  logs: addLog(prev, "Battle Start!") 
              };
          }
      });
  };

  const handleResourceOption = (type: 'ADD' | 'SWAP') => {
       if (type === 'ADD') {
           advancePhase(Phase.RESOURCE_ADD_SELECT);
       } else {
           advancePhase(Phase.RESOURCE_SWAP_SELECT_HAND);
       }
  };

  const cancelResourceAction = () => {
      advancePhase(Phase.RESOURCE_START);
  };

  const returnToSandbox = () => {
      if (!gameStateRef.current) return;
      setGameState(prev => prev ? { ...prev, isSandboxRun: false, phase: Phase.MAIN, turnPlayer: 0, activeCombatCardId: null, pendingAttackers: [] } : null);
  };

  const startPlayFromHere = (vsCpu: boolean) => {
       setGameState(prev => {
           if (!prev) return null;
           // Configure CPU
           const ps = [...prev.players];
           ps[1].isCpu = vsCpu;
           return { ...prev, players: ps, isSandboxRun: true, mode: 'SANDBOX' };
       });
       setShowPlaySetup(false);
       setSandboxToolsOpen(false);
  };

  const executeCardAction = (action: 'TAP' | 'DELETE') => {
      if (!cardActionTarget) return;
      setGameState(prev => {
          if(!prev) return null;
          const { card, loc, ownerId, instanceId } = cardActionTarget;
          const p = prev.players.find(pl => pl.id === ownerId)!;

          if (action === 'DELETE') {
              if (loc === 'HAND') p.hand = p.hand.filter(c => c.id !== card.id);
              else if (loc === 'FIELD') p.field = p.field.filter(f => f.instanceId !== instanceId);
              else if (loc === 'RESOURCE') p.resources = p.resources.filter(f => f.instanceId !== instanceId);
          } else if (action === 'TAP' && instanceId) {
               const list = loc === 'FIELD' ? p.field : p.resources;
               const target = list.find(f => f.instanceId === instanceId);
               if (target) target.isTapped = !target.isTapped;
          }
          return { ...prev, players: [...prev.players] };
      });
      setCardActionTarget(null);
  };

  if (!gameState) {
      return (
        <div className="relative flex flex-col items-center justify-center h-screen w-full bg-slate-950 overflow-hidden selection:bg-indigo-500/30">
            {/* Animated Background Elements */}
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-slate-900 via-slate-950 to-black z-0"></div>
            <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] opacity-30 z-0"></div>

            {/* Floating Suits Background */}
            <div className="absolute inset-0 overflow-hidden pointer-events-none z-0 opacity-20">
                <div className="absolute top-[10%] left-[10%] text-[12rem] text-slate-800 rotate-12 animate-pulse duration-[3000ms]">♠</div>
                <div className="absolute bottom-[10%] right-[5%] text-[14rem] text-red-900 -rotate-12 animate-pulse duration-[4000ms]">♥</div>
                <div className="absolute top-[20%] right-[15%] text-[10rem] text-slate-800 rotate-45 animate-pulse duration-[5000ms]">♣</div>
                <div className="absolute bottom-[20%] left-[8%] text-[11rem] text-red-900 -rotate-45 animate-pulse duration-[3500ms]">♦</div>
            </div>

            <MainMenu 
                menuStep={menuStep}
                setMenuStep={setMenuStep}
                handleModeSelect={handleModeSelect}
                handleStartGameClick={handleStartGameClick}
                handleSpectateClick={handleSpectateClick}
                startLesson={startLesson}
            />
        </div>
      );
  }

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);

  // HOTSEAT / SANDBOX View Logic
  // In Sandbox, View is determined by turnPlayer state which is manually toggled via "Switch Perspective"
  const isHotseat = !gameState.players[1].isCpu || gameState.mode === 'SANDBOX';
  const viewPlayerId = isHotseat ? gameState.turnPlayer : 0; 
  const bottomPlayer = gameState.players[viewPlayerId];
  const topPlayer = gameState.players[viewPlayerId === 0 ? 1 : 0];

  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = canDoAnything(gameState) && !gameState.isSandboxRun ? '' : 'ring-2 ring-indigo-400 animate-pulse';
  const isPlayerTurn = activeDecisionPlayerId === viewPlayerId;
  const isActivePlayerCpu = gameState.players[activeDecisionPlayerId].isCpu;

  // Interactive if it is the player's turn AND the player is NOT a CPU
  const isInteractive = isPlayerTurn && !isActivePlayerCpu;

  const discardCards = viewingDiscard === 'SHARED' ? [...gameState.players[0].discard, ...gameState.players[1].discard] 
    : (typeof viewingDiscard === 'number' ? gameState.players[viewingDiscard].discard : []);

  const tutorialComplete = gameState.tutorialState?.completed;

  return (
    <div 
      className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" 
      ref={containerRef}
      onMouseMove={(e) => {
          if (dragState) {
              setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null);
          }
      }}
      onMouseUp={(e) => {
          if (dragState) {
              handleDrop(e.nativeEvent, dragState);
              setDragState(null);
          }
      }}
      onClick={handleGlobalClick}
    >
      {/* Coin Flip Overlay */}
      {isCoinFlipping && (
           <CoinFlipOverlay 
                p1Name={gameState.players[0].name} 
                p2Name={gameState.players[1].name} 
                onComplete={(winner) => {
                    setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null);
                    setIsCoinFlipping(false);
                }} 
           />
      )}

      {/* Tutorial Overlay */}
      {gameState.tutorialState?.active && !tutorialComplete && gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex] && (
          <TutorialOverlay 
              step={gameState.tutorialState.steps[gameState.tutorialState.currentStepIndex]} 
              onNext={() => advanceTutorialStep('NEXT')}
          />
      )}

      {/* Tutorial Complete Screen */}
      {tutorialComplete && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <GraduationCap className="w-24 h-24 mx-auto text-emerald-500 animate-bounce" />
                  <h1 className="text-5xl md:text-7xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-500 drop-shadow-[0_0_25px_rgba(16,185,129,0.5)]">
                      TUTORIAL COMPLETE
                  </h1>
                  <h2 className="text-2xl text-slate-300">You have mastered the basics!</h2>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg font-bold text-xl shadow-lg shadow-emerald-500/30 transform transition-all hover:scale-105 active:scale-95 flex items-center gap-2">
                          <RotateCcw size={20} /> Return to Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {gameState.isSandboxRun && (
          <div className="absolute top-16 left-4 z-50 animate-in fade-in slide-in-from-top">
              <button onClick={returnToSandbox} className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-lg font-bold shadow-lg flex items-center gap-2">
                  <RotateCcw size={18}/> Return to Sandbox
              </button>
          </div>
      )}

      {/* Play Setup Modal */}
      {showPlaySetup && (
          <div className="absolute inset-0 z-[100] bg-black/80 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 w-80">
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2"><Play size={20} className="text-emerald-400"/> Play Scenario</h3>
                  <div className="space-y-3">
                      <button onClick={() => startPlayFromHere(true)} className="w-full bg-slate-800 hover:bg-emerald-900/30 border border-slate-700 hover:border-emerald-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Cpu size={18}/> Vs CPU
                      </button>
                      <button onClick={() => startPlayFromHere(false)} className="w-full bg-slate-800 hover:bg-amber-900/30 border border-slate-700 hover:border-amber-500/50 p-3 rounded text-left font-bold flex items-center gap-2">
                          <Users size={18}/> Hotseat
                      </button>
                  </div>
                  <button onClick={() => setShowPlaySetup(false)} className="mt-4 text-slate-500 text-sm hover:text-white">Cancel</button>
              </div>
          </div>
      )}

      {/* Card Action Modal for Sandbox */}
      {cardActionTarget && (
          <div className="absolute inset-0 z-[100] bg-black/50 flex items-center justify-center" onClick={() => setCardActionTarget(null)}>
              <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 shadow-2xl transform scale-100 transition-transform" onClick={e => e.stopPropagation()}>
                  <div className="flex justify-center mb-4">
                      <CardDisplay card={cardActionTarget.card} size="lg" />
                  </div>
                  <div className="flex gap-2 justify-center">
                      {cardActionTarget.loc !== 'HAND' && (
                          <button onClick={() => executeCardAction('TAP')} className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                              <RotateCcw size={16}/> Tap/Untap
                          </button>
                      )}
                      <button onClick={() => executeCardAction('DELETE')} className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2">
                          <Trash2 size={16}/> Remove
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Sandbox Floating Toggle */}
      {gameState.mode === 'SANDBOX' && !gameState.isSandboxRun && !sandboxToolsOpen && (
          <button 
            onClick={() => setSandboxToolsOpen(true)} 
            className="absolute top-20 right-4 z-50 bg-slate-800 p-3 rounded-full border border-slate-600 shadow-xl hover:bg-slate-700 text-amber-400"
          >
              <Edit3 size={24} />
          </button>
      )}

      {/* Render Sandbox Tools Panel */}
      {sandboxToolsOpen && (
          <SandboxTools 
              gameState={gameState}
              setGameState={setGameState}
              sandboxSearchTerm={sandboxSearchTerm}
              setSandboxSearchTerm={setSandboxSearchTerm}
              sandboxTargetPlayer={sandboxTargetPlayer}
              setSandboxTargetPlayer={setSandboxTargetPlayer}
              selectedSandboxCard={selectedSandboxCard}
              setSelectedSandboxCard={setSelectedSandboxCard}
              setSandboxToolsOpen={setSandboxToolsOpen}
              setShowPlaySetup={setShowPlaySetup}
          />
      )}

      {/* Turn Change Overlay */}
      {showTurnAnim && (
          <TurnChangeOverlay 
              playerName={gameState.players[gameState.turnPlayer].name}
              turnCount={gameState.turnCount}
              onComplete={handleTurnAnimComplete}
          />
      )}

      {gameState.phase === Phase.GAME_OVER && !tutorialComplete && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <h1 className="text-6xl md:text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 drop-shadow-[0_0_25px_rgba(234,179,8,0.5)] animate-bounce">
                      GAME OVER
                  </h1>
                  <h2 className="text-3xl font-bold text-white drop-shadow-md">
                      {gameState.winner !== null ? `${gameState.players[gameState.winner].name} Wins!` : "It's a Draw!"}
                  </h2>
                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-bold text-xl shadow-lg shadow-indigo-500/30 transform transition-all hover:scale-105 active:scale-95">
                          Rematch / Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showResignModal && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200 border-red-900/50 border-red-900/50">
                  <h3 className="text-xl font-bold font-title text-red-500 mb-2">Resign Game?</h3>
                  <p className="text-slate-400 mb-6">You will forfeit the match. Are you sure?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowResignModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={handleResign} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Resign</button>
                  </div>
              </div>
          </div>
      )}

      {/* Quit to Title Modal */}
      {showQuitModal && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">Quit to Title?</h3>
                  <p className="text-slate-400 mb-6">Current game progress will be lost.</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowQuitModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={handleQuitToTitle} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Quit</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>

                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>

                  <div className="flex items-center justify-center gap-3 bg-slate-800 p-3 rounded-lg">
                      <input 
                        type="checkbox" 
                        id="menuSort" 
                        checked={autoSort} 
                        onChange={toggleAutoSort}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="menuSort" className="text-slate-300 select-none cursor-pointer font-bold text-sm">Auto-Sort Hand</label>
                  </div>

                  <button onClick={() => setShowResignModal(true)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Resign
                  </button>
                  <button onClick={() => setShowQuitModal(true)} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2">
                      <ArrowRight size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Discard Modal */}
      {viewingDiscard !== null && (
          <div className="absolute inset-0 z-[110] flex items-center justify-center bg-black/90 backdrop-blur-md" onClick={() => setViewingDiscard(null)}>
               <div className="relative w-full max-w-4xl p-8 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl max-h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-2xl font-bold font-title text-white flex items-center gap-3">
                            <Trash2 className="text-slate-500" />
                            {viewingDiscard === 'SHARED' ? 'Shared Graveyard' : `${gameState.players[viewingDiscard].name}'s Graveyard`}
                        </h2>
                        <button onClick={() => setViewingDiscard(null)} className="p-2 hover:bg-slate-800 rounded-full transition-colors">
                            <X size={24} className="text-slate-400" />
                        </button>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 bg-slate-950/50 rounded-lg border border-slate-800">
                        {discardCards.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-48 text-slate-600 italic">
                                No cards in graveyard.
                            </div>
                        ) : (
                            <div className="flex flex-wrap gap-4 justify-center">
                                {discardCards.map((c, i) => (
                                    <div key={i} className="hover:scale-110 transition-transform">
                                        <CardDisplay card={c} size="md" />
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="mt-4 text-center text-xs text-slate-500 font-bold uppercase tracking-wider">
                        {discardCards.length} Cards
                    </div>
               </div>
          </div>
      )}

      {specialAnim && <SpecialCardAnimation type={specialAnim.type} card={specialAnim.card} targetRect={specialAnim.targetRect} onComplete={() => setSpecialAnim(null)} />}

      {flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {explosions.map(e => (
          <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => setExplosions(prev => prev.filter(x => x.id !== e.id))} />
      ))}

      {damageAnims.map(da => (
