                  <div className="flex gap-4 justify-center mt-8">
                      <button onClick={handleQuitToTitle} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-bold text-xl shadow-lg shadow-indigo-500/30 transform transition-all hover:scale-105 active:scale-95">
                          Rematch / Menu
                      </button>
                  </div>
              </div>
          </div>
      )}

      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button>
                  </div>
              </div>
          </div>
      )}

      {showResignModal && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200 border-red-900/50 border-red-900/50">
                  <h3 className="text-xl font-bold font-title text-red-500 mb-2">Resign Game?</h3>
                  <p className="text-slate-400 mb-6">You will forfeit the match. Are you sure?</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowResignModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={handleResign} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Resign</button>
                  </div>
              </div>
          </div>
      )}

      {/* Quit to Title Modal */}
      {showQuitModal && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">Quit to Title?</h3>
                  <p className="text-slate-400 mb-6">Current game progress will be lost.</p>
                  <div className="flex gap-3 justify-end">
                      <button onClick={() => setShowQuitModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button>
                      <button onClick={handleQuitToTitle} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Quit</button>
                  </div>
              </div>
          </div>
      )}

      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>

                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2">
                      <Play size={18} /> Resume
                  </button>

                  <div className="flex items-center justify-center gap-3 bg-slate-800 p-3 rounded-lg">
                      <input 
                        type="checkbox" 
                        id="menuSort" 
                        checked={autoSort} 
                        onChange={toggleAutoSort}
                        className="w-5 h-5 accent-indigo-500"
                      />
                      <label htmlFor="menuSort" className="text-slate-300 select-none cursor-pointer font-bold text-sm">Auto-Sort Hand</label>
                  </div>

                  <button onClick={() => setShowResignModal(true)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900">
                      <LogOut size={18} /> Resign
                  </button>
                  <button onClick={() => setShowQuitModal(true)} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2">
                      <ArrowRight size={18} /> Quit to Title
                  </button>
              </div>
          </div>
      )}

      {/* Discard Modal */}
      {viewingDiscard !== null && (
          <div className="absolute inset-0 z-[110] flex items-center justify-center bg-black/90 backdrop-blur-md" onClick={() => setViewingDiscard(null)}>
               <div className="relative w-full max-w-4xl p-8 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl max-h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-2xl font-bold font-title text-white flex items-center gap-3">
                            <Trash2 className="text-slate-500" />
                            {viewingDiscard === 'SHARED' ? 'Shared Graveyard' : `${gameState.players[viewingDiscard].name}'s Graveyard`}
                        </h2>
                        <button onClick={() => setViewingDiscard(null)} className="p-2 hover:bg-slate-800 rounded-full transition-colors">
                            <X size={24} className="text-slate-400" />
                        </button>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 bg-slate-950/50 rounded-lg border border-slate-800">
                        {discardCards.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-48 text-slate-600 italic">
                                No cards in graveyard.
                            </div>
                        ) : (
                            <div className="flex flex-wrap gap-4 justify-center">
                                {discardCards.map((c, i) => (
                                    <div key={i} className="hover:scale-110 transition-transform">
                                        <CardDisplay card={c} size="md" />
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="mt-4 text-center text-xs text-slate-500 font-bold uppercase tracking-wider">
                        {discardCards.length} Cards
                    </div>
               </div>
          </div>
      )}

      {specialAnim && <SpecialCardAnimation type={specialAnim.type} card={specialAnim.card} targetRect={specialAnim.targetRect} onComplete={() => setSpecialAnim(null)} />}

      {flyingCards.map(fc => (
          <Flyer key={fc.id} fc={fc} />
      ))}

      {flyingTexts.map(ft => (
          <div 
             key={ft.id}
             className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md"
             style={{ 
                 left: ft.startX, 
                 top: ft.startY,
                 transition: 'all 1s ease-in-out',
                 transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`,
                 opacity: 0,
                 animation: 'fly 1s forwards'
             }}
          >
              {ft.text}
              <style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style>
          </div>
      ))}

      {explosions.map(e => (
          <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => setExplosions(prev => prev.filter(x => x.id !== e.id))} />
      ))}

      {damageAnims.map(da => (
          <DamageOverlay 
            key={da.id}
            dmg={da.val} 
            targetRef={da.playerId === topPlayer.id ? lifeIconRef : bottomLifeRef}
            onComplete={() => setDamageAnims(prev => prev.filter(a => a.id !== da.id))}
          />
      ))}

      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">
          {Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => {
              const blockerEl = document.getElementById(blockerId);
              const attackerEl = document.getElementById(attackerId);
              if (blockerEl && attackerEl) {
                  const bRect = blockerEl.getBoundingClientRect();
                  const aRect = attackerEl.getBoundingClientRect();
                  return (
                      <line 
                        key={`${blockerId}-${attackerId}`}
                        x1={bRect.left + bRect.width/2}
                        y1={bRect.top + bRect.height/2}
                        x2={aRect.left + aRect.width/2}
                        y2={aRect.top + aRect.height/2}
                        stroke="#3b82f6"
                        strokeWidth="4"
                        strokeDasharray="0"
                        className="opacity-70"
                      />
                  );
              }
              return null;
          })}
          {dragState?.sourceType === 'FIELD' && dragState.currentX && (
               (() => {
                   const startEl = document.getElementById(dragState.instanceId!);
                   if(startEl) {
                       const rect = startEl.getBoundingClientRect();
                       return (
                           <line 
                                x1={rect.left + rect.width/2} y1={rect.top + rect.height/2}
                                x2={dragState.currentX} y2={dragState.currentY}
                                stroke="#3b82f6" strokeWidth="4" strokeDasharray="5" className="opacity-70"
                           />
                       );
                   }
               })()
          )}
      </svg>

      {isMobile ? (
          <div className="flex flex-col h-full bg-slate-950 select-none">
          {/* Mobile Top Bar: CPU Info */}
          <div className="h-14 bg-slate-900 border-b border-slate-800 flex items-center justify-between px-3 shadow-md z-30 shrink-0">
               <div className="flex items-center gap-3">
                   <button onClick={() => setShowMenu(true)} className="p-1.5 bg-slate-800 rounded text-slate-400">
                       <Menu size={18} />
                   </button>
                   <div className="flex flex-col leading-tight">
                       <span className="text-xs font-bold text-indigo-300">{topPlayer.name}</span>
                       <div className="flex items-center gap-2 text-xs text-slate-500" ref={topDeckRef}>
                           <span>Deck: {gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span>
                       </div>
                   </div>
               </div>

               {/* Center Turn Info */}
               <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center">
                    <span className="font-title font-bold text-amber-500 text-sm">TURN {gameState.turnCount}</span>
                    <span className="text-[10px] text-slate-400 uppercase tracking-wider">{getPhaseName()}</span>
               </div>

               <div className="flex items-center gap-3" ref={lifeIconRef}>
                   <div className="flex items-center gap-1 text-red-400 font-black text-xl">
                       <Heart size={20} fill="currentColor" /> {topPlayer.life}
                   </div>
                   {gameState.mode === 'PRO' && (
                        <button onClick={() => setViewingDiscard(topPlayer.id)} className="text-slate-500">
                            <Trash2 size={16} />
                        </button>
                   )}
               </div>
          </div>

          {/* Mobile Field Area */}
          <div id="field-area" className="flex-1 relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] overflow-hidden flex flex-col">

              {/* Log Toggle Button */}
              <button 
                onClick={() => setShowMobileLog(!showMobileLog)} 
                className={`absolute top-2 left-2 z-40 p-2 rounded-full border shadow-lg transition-colors ${showMobileLog ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-slate-900/80 border-slate-700 text-slate-400'}`}
              >
                  {showMobileLog ? <X size={16} /> : <div className="text-[10px] font-bold">LOG</div>}
              </button>

              {/* Mobile Log Overlay */}
              {showMobileLog && (
                  <div className="absolute top-12 left-2 right-2 bottom-auto max-h-48 z-40 bg-black/80 backdrop-blur-md border border-slate-700 rounded-lg overflow-y-auto p-2 flex flex-col-reverse gap-1 shadow-2xl">
                      {gameState.logs.map((log) => (
                          <div key={log.id} className="text-xs text-slate-300 border-l-2 border-indigo-500 pl-2">
                              <LogRenderer text={log.text} />
                          </div>
                      ))}
                  </div>
              )}

              {/* Top Player Zone */}
              <div className="flex-1 flex flex-col items-center justify-start py-2 space-y-2 relative">
                  {/* CPU Hand */}
                  <div className="flex -space-x-6 scale-75 opacity-90 h-12" ref={cpuHandRef}>
                       {topPlayer.hand.map(c => <CardDisplay key={c.id} domId={c.id} card={c} showBack={gameState.mode !== 'SANDBOX'} size="sm" onClick={() => handleCardClick(c, 'HAND', topPlayer.id)} />)}
                  </div>

                  {/* CPU Field & Resources Row */}
                  <div className="w-full flex justify-between px-1 items-start gap-1">
                       {/* Field (Flex, takes available space) */}
                       <div className="flex-1 flex justify-center gap-1 overflow-x-auto px-1 min-h-[80px]">
                            {/* Black Lane */}
                            <div className="bg-slate-900/40 p-1 rounded border border-slate-700/50 flex gap-1 min-w-[50px] items-center justify-center">
                                {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                                    <div key={fc.instanceId} className="scale-75 origin-top -mx-2">
                                        <CardDisplay 
                                            domId={fc.instanceId}
                                            data-instance-id={fc.instanceId}
                                            card={fc.card} 
                                            isTapped={fc.isTapped}
                                            isSummoningSick={fc.isSummoningSick}
                                            size="sm"
                                            isLunging={gameState.activeCombatCardId === fc.instanceId}
                                            damageTaken={gameState.recentDamage[fc.instanceId]}
                                            attachedCards={fc.attachedCards}
                                            orientation="top"
                                            onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                        />
                                    </div>
                                ))}
                            </div>
                            {/* Red Lane */}
                            <div className="bg-red-900/20 p-1 rounded border border-red-900/30 flex gap-1 min-w-[50px] items-center justify-center">
                                {topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (
                                    <div key={fc.instanceId} className="scale-75 origin-top -mx-2">
                                        <CardDisplay 
                                            domId={fc.instanceId}
                                            data-instance-id={fc.instanceId}
                                            card={fc.card} 
                                            isTapped={fc.isTapped}
                                            isSummoningSick={fc.isSummoningSick} 
                                            size="sm"
                                            isLunging={gameState.activeCombatCardId === fc.instanceId}
                                            damageTaken={gameState.recentDamage[fc.instanceId]}
                                            attachedCards={fc.attachedCards}
                                            orientation="top"
                                            onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}
                                        />
                                    </div>
                                ))}
                            </div>
                       </div>

                       {/* Resources (Right) */}
                       <div className="flex items-center gap-1 scale-75 origin-top-right shrink-0">
                           <div className="text-[12px] font-bold text-slate-500 bg-slate-900/80 px-1.5 py-0.5 rounded border border-slate-700">
                               {topPlayer.resources.length}
                           </div>
                           <div id={`resource-container-${topPlayer.id}`} className="flex flex-col items-center -space-y-10">
                                {topPlayer.resources.map((r, i) => (
                                    <div key={r.instanceId} style={{ zIndex: i }} onClick={() => handleCardClick(r.card, 'RESOURCE', topPlayer.id, r.instanceId)}>
                                        <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" isSummoningSick={false} />
                                    </div>
                                ))}
                           </div>
                       </div>
                  </div>
              </div>

              {/* Bottom Player Zone */}
              <div className="flex-1 flex flex-col justify-end py-2 space-y-2 relative border-t border-slate-800/30">
                  <div className="w-full flex justify-between px-1 items-end mb-2 gap-1">
                       {/* Resources (Left) - Safe from FABs */}
                       <div className="flex items-center gap-1 scale-75 origin-bottom-left shrink-0 z-20">
                            <div id={`resource-container-${bottomPlayer.id}`} className="grid grid-cols-2 gap-4">
                                <div className="flex flex-col -space-y-20 relative z-10">
                                     {bottomPlayer.resources.slice(0, 5).map((r, i) => (
                                        <div key={r.instanceId} id={r.instanceId} style={{ zIndex: i }} onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}>
                                            <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" isSummoningSick={false} />
                                        </div>
                                     ))}
                                </div>
                                <div className="flex flex-col -space-y-20 relative z-0">
                                     {bottomPlayer.resources.slice(5, 10).map((r, i) => (
                                        <div key={r.instanceId} id={r.instanceId} style={{ zIndex: i }} onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}>
                                            <CardDisplay card={r.card} isTapped={r.isTapped} size="sm" isSummoningSick={false} />
                                        </div>
                                     ))}
                                </div>
                            </div>
                            <div className="text-[12px] font-bold text-indigo-400 bg-slate-900/80 px-1.5 py-0.5 rounded border border-slate-700">
                                {bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}
                            </div>
                       </div>

                       {/* Field (Right) */}
                       <div className="flex-1 flex justify-center gap-1 overflow-x-auto px-1 min-h-[80px]">
                            {/* Black Lane */}
                            <div className="bg-slate-900/40 p-1 rounded border border-slate-700/50 flex gap-1 min-w-[50px] items-center justify-center">
                                 {bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (
                                     <div key={fc.instanceId} className="scale-75 origin-bottom -mx-2">
                                         <CardDisplay 
                                            domId={fc.instanceId}
                                            data-instance-id={fc.instanceId}
                                            card={fc.card} 
                                            isTapped={fc.isTapped}
                                            isSummoningSick={fc.isSummoningSick} 
                                            size="sm"
                                            isAttacking={gameState.pendingAttackers.includes(fc.instanceId)}
                                            isBlocking={!!gameState.pendingBlocks[fc.instanceId]}
                                            isLunging={gameState.activeCombatCardId === fc.instanceId}
                                            damageTaken={gameState.recentDamage[fc.instanceId]}
                                            attachedCards={fc.attachedCards}
                                            onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                            onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)}
                                            isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick}
                                            orientation="bottom"
                                         />
                                     </div>
                                 ))}
